export function createDynamicBodyView(buffer: SharedArrayBuffer): ArrayOfBufferBackedObjects;
/**
 * Create a BBO view for kinematic bodies from a SharedArrayBuffer.
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {ArrayOfBufferBackedObjects} BBO array view
 */
export function createKinematicBodyView(buffer: SharedArrayBuffer): ArrayOfBufferBackedObjects;
/**
 * Create a BBO view for camera state from a SharedArrayBuffer.
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {BufferBackedObject} BBO view (single object)
 */
export function createCameraView(buffer: SharedArrayBuffer): BufferBackedObject;
/**
 * Create a BBO view for zone triggers from a SharedArrayBuffer.
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {ArrayOfBufferBackedObjects} BBO array view
 */
export function createZoneView(buffer: SharedArrayBuffer): ArrayOfBufferBackedObjects;
/**
 * Create a BBO view for static bodies from a SharedArrayBuffer.
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {ArrayOfBufferBackedObjects} BBO array view
 */
export function createStaticBodyView(buffer: SharedArrayBuffer): ArrayOfBufferBackedObjects;
/**
 * Create a view for in-reach triggers from a SharedArrayBuffer.
 * Uses raw Float32Array for simplicity (4 floats per item: used, x, y, z).
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {Float32Array} Typed array view with _itemLength property
 */
export function createInReachView(buffer: SharedArrayBuffer): Float32Array;
/**
 * Create a BBO view for global physics state from a SharedArrayBuffer.
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {BufferBackedObject} BBO view (single object)
 */
export function createPhysicsGlobalView(buffer: SharedArrayBuffer): BufferBackedObject;
/**
 * Create a view for pointer input from a SharedArrayBuffer.
 * Uses raw Float32Array (6 floats: click, x, y, hitX, hitY, hitZ).
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {Float32Array} Typed array view with _itemLength property
 */
export function createPointerView(buffer: SharedArrayBuffer): Float32Array;
/**
 * Create a BBO view for companion state from a SharedArrayBuffer.
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {BufferBackedObject} BBO view (single object)
 */
export function createCompanionView(buffer: SharedArrayBuffer): BufferBackedObject;
/**
 * Create a view for rayshoot requests from a SharedArrayBuffer.
 * Uses raw Float32Array for fire requests (16 floats per request).
 *
 * Schema:
 * [0]: active (1 = fire requested, 0 = idle)
 * [1]: shooterIndex
 * [2]: shooterType (0 = dynamic, 1 = kinematic)
 * [3-5]: originX, originY, originZ
 * [6-8]: directionX, directionY, directionZ
 * [9]: maxDistance
 * [10]: piercing (0 = first hit only, 1 = all hits)
 * [11]: fromCamera (0 = use origin/direction, 1 = use camera)
 * [12-15]: reserved
 *
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {Float32Array} Typed array view with _itemLength property
 * @deprecated Use createWeaponsView instead
 */
export function createRayshootView(buffer: SharedArrayBuffer): Float32Array;
/**
 * Create a BBO view for projectiles from a SharedArrayBuffer.
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {ArrayOfBufferBackedObjects} BBO array view
 */
export function createProjectileView(buffer: SharedArrayBuffer): ArrayOfBufferBackedObjects;
/**
 * Create a view for weapon requests from a SharedArrayBuffer.
 * Uses raw Float32Array for fire requests (32 floats per request slot).
 *
 * Schema:
 * [0]: active (1 = fire requested, 0 = idle)
 * [1]: weaponType (0 = hitscan, 1 = projectile, 2 = hybrid)
 * [2]: shooterIndex
 * [3]: shooterType (0 = dynamic, 1 = kinematic)
 * [4-6]: originX, originY, originZ
 * [7-9]: directionX, directionY, directionZ
 * [10]: maxDistance
 * [11]: piercing (0 = first hit only, 1 = all hits)
 * [12]: fromCamera (0 = use origin/direction, 1 = use camera)
 * [13]: damage
 * [14]: projectileSpeed (for projectile/hybrid)
 * [15]: gravityMultiplier
 * [16]: drag
 * [17]: lifetime
 * [18]: aoeRadius
 * [19-31]: reserved
 *
 * @param {SharedArrayBuffer} buffer - The shared buffer
 * @returns {Float32Array} Typed array view with _itemLength property
 */
export function createWeaponsView(buffer: SharedArrayBuffer): Float32Array;
